# -*- coding: utf-8 -*-
from .base import FrameworkPack, LanguageBranch, BestPractice, LanguageModule, sec, eng
SECURITY=[sec('GO-SEC-SQLI-01','SQL via Sprintf','critical',r'(?:db|tx)\.(?:Query|Exec|QueryRow)\s*\(\s*fmt\.Sprintf','SQL built via Sprintf.','Use placeholders',cwe='CWE-89'),sec('GO-SEC-CMDI-01','Shell command','critical',r'exec\.Command\s*\(\s*["\'](?:sh|bash|cmd)["\']\s*,\s*["\']-c','Shell injection.','Call executable directly',cwe='CWE-78'),sec('GO-SEC-CMDI-02','Command Sprintf','critical',r'exec\.Command\s*\(\s*fmt\.Sprintf','Command args injection.','Pass args separately',cwe='CWE-78'),sec('GO-SEC-PATH-01','Path concat','high',r'os\.(?:Open|ReadFile|Create)\s*\([^)]*\+','Path traversal.','Validate base path',cwe='CWE-22'),sec('GO-SEC-SSRF-01','HTTP user URL','critical',r'http\.(?:Get|Post|Head)\s*\([^)]*(?:user|url|req|r\.)','SSRF.','Whitelist destinations',cwe='CWE-918'),sec('GO-SEC-CRYPTO-01','Weak hash','medium',r'(?:md5|sha1)\.(?:New|Sum)','Weak hash.','Use SHA-256+',cwe='CWE-327'),sec('GO-SEC-RAND-01','math/rand','medium',r'math/rand|rand\.(?:Int|Intn)','Predictable random.','Use crypto/rand',cwe='CWE-338'),sec('GO-SEC-TLS-01','TLS verification disabled','high',r'InsecureSkipVerify\s*:\s*true','TLS bypass.','Remove the bypass',cwe='CWE-295'),sec('GO-SEC-SECRET-01','Hardcoded secret','high',r'(?:password|secret|token|apiKey)\s*(?::=|=)\s*["\'][^"\']{6,}["\']','Hardcoded credential.','Use environment secrets',cwe='CWE-798'),sec('GO-SEC-TMPL-01','text/template','high',r'text/template','No HTML escaping.','Use html/template',cwe='CWE-79'),sec('GO-SEC-DOS-01','Unbounded ReadAll','medium',r'io\.ReadAll\s*\(\s*r\.Body\s*\)','Memory DoS.','Use LimitReader',cwe='CWE-770'),sec('GO-SEC-UNSAFE-01','unsafe.Pointer','high',r'unsafe\.Pointer','Unsafe memory access.','Avoid unsafe',cwe='CWE-787'),sec('GO-SEC-REDIR-01','Open redirect','medium',r'http\.Redirect\s*\([^,]+,\s*r\.URL\.Query','Redirect input.','Whitelist local paths',cwe='CWE-601'),sec('GO-SEC-GOB-01','gob decoder','critical',r'gob\.NewDecoder','Untrusted gob data.','Use bounded JSON',cwe='CWE-502'),sec('GO-SEC-XML-01','XML parser','medium',r'xml\.(?:NewDecoder|Unmarshal)','Review XML handling.','Harden inputs',cwe='CWE-611'),sec('GO-SEC-JWT-01','JWT none','critical',r'SigningMethodNone|UnsafeAllowNoneSignatureType','Unsigned JWT.','Enforce algorithm',cwe='CWE-347'),sec('GO-SEC-JWT-02','JWT unverified','high',r'ParseUnverified','Unverified JWT.', 'Verify signatures',cwe='CWE-347'),sec('GO-SEC-CTX-01','HTTP without context','medium',r'http\.(?:Get|Post|Head)\s*\(','No timeout/context.', 'Use client timeout',cwe='CWE-400'),sec('GO-SEC-YAML-01','YAML unmarshal','high',r'yaml\.(?:Unmarshal|NewDecoder)','Untrusted YAML.', 'Limit and validate input',cwe='CWE-502'),sec('GO-SEC-CRYPTO-02','DES cipher','high',r'des\.NewCipher','Weak DES.', 'Use AES-GCM',cwe='CWE-327')]
ENGINEERING=[eng(f'GO-ENG-{i:02d}',n,s,p,d,fix) for i,(n,s,p,d,fix) in enumerate([('Ignored error','medium',r'_\s*=','Error ignored.','Handle errors.'),('Goroutine','medium',r'\bgo\s+func','Cancellation unclear.','Propagate context.'),('Panic','medium',r'\bpanic\s*\(','Avoid panic.','Return error.'),('log.Fatal','medium',r'log\.Fatal','Exits process.','Return error.'),('fmt.Print','low',r'fmt\.Print','Use structured logging.','Use slog.'),('TODO','info',r'//\s*(?:TODO|FIXME)','Unresolved marker.','Create issue.'),('context.Background','low',r'context\.Background','Propagate caller context.','Pass context.'),('interface{}','low',r'interface\s*\{\s*\}','Prefer any/generics.','Use precise types.')],1)]
GIN=FrameworkPack('Gin','1.10+','https://gin-gonic.com/',[sec('GO-GIN-01','Trusted proxies','medium',r'SetTrustedProxies','Proxy trust review.','Allowlist proxies',cwe='CWE-346')])
ECHO=FrameworkPack('Echo','4.x','https://echo.labstack.com/',[sec('GO-ECHO-01','Recover middleware','medium',r'echo\.New','Add Recover middleware.','Use middleware.Recover()')])
FIBER=FrameworkPack('Fiber','2.x','https://docs.gofiber.io/',[sec('GO-FIBER-01','Helmet middleware','medium',r'fiber\.New','Add Helmet.','Use helmet middleware')])
NET=FrameworkPack('net/http','stdlib','https://pkg.go.dev/net/http',[sec('GO-NET-01','Server timeout','medium',r'http\.Server','Set timeouts.','ReadTimeout/WriteTimeout',cwe='CWE-400')])
BRANCHES=[LanguageBranch('web_backend','REST APIs',['SQLi','SSRF'],['SSRF'],['GO-SEC-SQLI-01','GO-SEC-SSRF-01']),LanguageBranch('cli_tools','CLI tools',['Commands'],['RCE'],['GO-SEC-CMDI-01']),LanguageBranch('cloud_infra','Cloud native',['Secrets'],['Leaks'],['GO-SEC-SECRET-01']),LanguageBranch('microservices','Services',['Timeouts'],['DoS'],['GO-SEC-CTX-01']),LanguageBranch('systems_programming','Systems',['unsafe'],['Memory'],['GO-SEC-UNSAFE-01'])]
LANGUAGE=LanguageModule('go','1.21+',['.go'],'Go knowledge base','https://go.dev/doc/',SECURITY,ENGINEERING,[GIN,ECHO,FIBER,NET],BRANCHES,[BestPractice('Check errors','Handle every error.','if err != nil { return err }','_ = fn()')])
